package ca.yorku.eecs3311.coursepilot.application.agent;
import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class AgentPlanningTest {@Test void weaknessRequestCreatesObservableMultiStepPlan(){var intent=new IntentAnalyzer().analyze("Help me study what I am weakest at");var plan=new TaskPlanner().plan(intent);assertEquals(AgentIntent.WEAK_TOPIC_SUPPORT,intent);assertEquals(3,plan.steps().size());}@Test void validatorRejectsUnknownTools(){var validator=new AgentPlanValidator();var plan=new AgentPlan(AgentIntent.PROGRESS_REVIEW,java.util.List.of(new AgentPlanStep("SHELL",java.util.Map.of())));assertThrows(IllegalArgumentException.class,()->validator.validate(plan,1L));}@Test void validatorAllowsGroundedStudyTools(){var validator=new AgentPlanValidator();var plan=new AgentPlan(AgentIntent.PROGRESS_REVIEW,java.util.List.of(new AgentPlanStep("GENERATE_QUIZ",java.util.Map.of()),new AgentPlanStep("CREATE_STUDY_PLAN",java.util.Map.of())));assertDoesNotThrow(()->validator.validate(plan,1L));}@Test void analyzerMapsAssetRequests(){var analyzer=new IntentAnalyzer();assertEquals(AgentIntent.QUIZ_GENERATION,analyzer.analyze("quiz me"));assertEquals(AgentIntent.STUDY_PLAN_CREATION,analyzer.analyze("create a study plan"));}}
